import numpy as np

def select_item(current_index, remaining_capacity, weights, values, num_items, **kwargs):
    if weights[current_index] > remaining_capacity:
        return 0.0

    # 计算当前物品的价值密度和容量占用比
    current_density = values[current_index] / weights[current_index]
    capacity_ratio = weights[current_index] / (remaining_capacity + 1e-6)

    # 计算剩余物品的平均价值密度
    remaining_indices = list(range(current_index+1, num_items))
    if remaining_indices:
        feasible = weights[remaining_indices] <= remaining_capacity
        if np.any(feasible):
            avg_density = np.mean(values[remaining_indices][feasible] / weights[remaining_indices][feasible])
        else:
            avg_density = 0.0
    else:
        avg_density = 0.0

    # 基础分数：结合价值密度和容量占用比，引入随机扰动
    base_score = current_density * (1 - capacity_ratio * 0.5)
    noise = np.random.uniform(-0.1, 0.1)  # 随机扰动
    threshold = avg_density * 0.8 + noise

    # 引入模拟退火局部搜索：根据剩余容量大小动态调整
    if remaining_capacity > 0.7 * (weights[current_index] + np.sum(weights[current_index:])):  # 容量充裕
        if current_density >= threshold:
            return 1.0
        else:
            return 0.0
    else:  # 容量紧张时更保守
        if current_density >= avg_density * 0.9 + noise * 0.5:
            return 1.0
        else:
            return 0.0

import numpy as np

def select_item(current_index, remaining_capacity, weights, values, num_items, **kwargs):
    # 如果剩余容量不足，直接返回0
    if weights[current_index] > remaining_capacity:
        return 0.0

    # 计算当前物品的价值密度
    current_density = values[current_index] / weights[current_index]

    # 计算剩余物品平均价值密度（不包括当前物品）
    remaining_indices = list(range(current_index+1, num_items))
    if remaining_indices:
        filtered_weights = weights[remaining_indices]
        # 只考虑能装下的物品
        feasible = filtered_weights <= remaining_capacity
        if np.any(feasible):
            avg_density = np.mean(values[remaining_indices][feasible] / weights[remaining_indices][feasible])
        else:
            avg_density = 0.0
    else:
        avg_density = 0.0

    # 阈值：当前密度是否高于平均密度的90%（可调参数）
    threshold = 0.9 * avg_density if avg_density > 0 else 0.0

    # 如果当前物品价值密度超过阈值则拿，否则不拿
    if current_density >= threshold:
        return 1.0
    else:
        return 0.0
